package br.com.onda;

import android.app.Activity;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.media3.common.*;
import androidx.media3.session.*;
import androidx.media3.session.MediaController;
import com.google.common.util.concurrent.ListenableFuture;
import java.util.*;
import java.util.concurrent.*;

@androidx.media3.common.util.UnstableApi
public class DjActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private Future<?> pending;private int generation;private boolean loaded;
    private final List<MediaItem> library=new ArrayList<>(),queue=new ArrayList<>();private final Map<String,DjPlanner.Song> details=new HashMap<>();
    private MediaController player;private ListenableFuture<MediaController> connection;private Spinner mode,size;private TextView status;private Button play,refresh;private BaseAdapter adapter;
    private final Handler handler=new Handler(Looper.getMainLooper());private static final int[] SIZES={15,30,60};
    @Override public void onCreate(Bundle state){super.onCreate(state);
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,20),Ui.dp(this,12)+i.getSystemWindowInsetTop(),Ui.dp(this,20),Ui.dp(this,12)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
        LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);Button back=Ui.button(this,"‹",v->finish());back.setContentDescription("Voltar");Ui.ghost(back);header.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));TextView title=Ui.text(this,"DJ Pessoal",25,Ui.TEXT);Ui.bold(title);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button menu=Ui.menuButton(this,"Menu do DJ Pessoal",v->Ui.menu(this,v,new String[]{"Ajustar sessão","Comando de voz","Como funciona"},new String[]{"Ajustar sessão do DJ Pessoal","Comandar DJ Pessoal por voz","Como funciona o DJ Pessoal"},new Runnable[]{()->DjControls.show(this,player),()->VoiceSearch.start(this,true),()->new android.app.AlertDialog.Builder(this).setTitle("Seu DJ no celular").setMessage("Usa favoritas, escutas e faixas que você ouviu até o fim no Onda. Cada escolha mostra um motivo. Só calcula quando você pede e não envia o histórico para um servidor. O reconhecimento de fala depende do serviço Android.").setPositiveButton("Entendi",null).show()}));header.addView(menu,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));root.addView(header);
        TextView intro=Ui.text(this,"Escolhas do seu celular, com favoritas e histórico. Ajustes e voz ficam no menu ☰.",14,Ui.MUTED);intro.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,12));root.addView(intro);
        LinearLayout controls=new LinearLayout(this);mode=new Spinner(this);mode.setContentDescription("Modo do DJ");mode.setAdapter(new ArrayAdapter<>(this,R.layout.spinner_item,new String[]{"Para você","Só favoritas","Redescobrir","Minha viagem","Downloads e redescobertas"}));Ui.spinner(mode);controls.addView(mode,new LinearLayout.LayoutParams(0,Ui.dp(this,48),2));size=new Spinner(this);size.setContentDescription("Tamanho da fila do DJ");size.setAdapter(new ArrayAdapter<>(this,R.layout.spinner_item,new String[]{"Até 15 músicas","Até 30 músicas","Até 60 músicas"}));Ui.spinner(size);LinearLayout.LayoutParams sizeParams=new LinearLayout.LayoutParams(0,Ui.dp(this,48),2);sizeParams.leftMargin=Ui.dp(this,8);controls.addView(size,sizeParams);root.addView(controls);
        SharedPreferences preferences=getSharedPreferences("dj",0);mode.setSelection(Math.max(0,Math.min(4,preferences.getInt("mode",0))));size.setSelection(Math.max(0,Math.min(2,preferences.getInt("size",1))));
        status=Ui.text(this,"Lendo biblioteca…",13,Ui.CYAN);status.setContentDescription("Estado da seleção do DJ");status.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,10));root.addView(status);
        ListView list=new ListView(this);list.setDivider(null);list.setDividerHeight(Ui.dp(this,6));list.setContentDescription("Fila criada pelo DJ");adapter=new BaseAdapter(){public int getCount(){return queue.size();}public Object getItem(int i){return queue.get(i);}public long getItemId(int i){return i;}public View getView(int i,View reused,ViewGroup parent){LinearLayout row;TextView title,subtitle;if(reused==null){row=new LinearLayout(DjActivity.this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(Ui.dp(DjActivity.this,14),Ui.dp(DjActivity.this,12),Ui.dp(DjActivity.this,14),Ui.dp(DjActivity.this,12));Ui.card(row,false);title=Ui.text(DjActivity.this,"",15,Ui.TEXT);Ui.bold(title);title.setMaxLines(1);title.setEllipsize(android.text.TextUtils.TruncateAt.END);subtitle=Ui.text(DjActivity.this,"",12,Ui.MUTED);subtitle.setMaxLines(2);subtitle.setPadding(0,Ui.dp(DjActivity.this,6),0,0);row.addView(title);row.addView(subtitle);row.setTag(new TextView[]{title,subtitle});}else{row=(LinearLayout)reused;TextView[] texts=(TextView[])row.getTag();title=texts[0];subtitle=texts[1];}MediaItem item=queue.get(i);title.setText((i+1)+". "+item.mediaMetadata.title);subtitle.setText(item.mediaMetadata.artist+" • "+DjSession.reason(item));row.setContentDescription("Ouvir seleção a partir de "+item.mediaMetadata.title);return row;}};list.setAdapter(adapter);list.setOnItemClickListener((p,v,position,id)->start(position));root.addView(list,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout actions=new LinearLayout(this);refresh=Ui.button(this,"Nova mistura",v->mix());refresh.setContentDescription("Gerar nova mistura do DJ");play=Ui.button(this,"Ouvir seleção",v->start(0));play.setContentDescription("Tocar seleção do DJ");Ui.primary(play);actions.addView(refresh,new LinearLayout.LayoutParams(0,Ui.dp(this,48),1));LinearLayout.LayoutParams playParams=new LinearLayout.LayoutParams(0,Ui.dp(this,48),1);playParams.leftMargin=Ui.dp(this,8);actions.addView(play,playParams);root.addView(actions);refresh.setEnabled(false);play.setEnabled(false);
        TextView note=Ui.text(this,"Seleção local sob demanda. Ouvir seleção inicia outra fila; ajustes preservam a música atual.",11,Ui.MUTED);note.setPadding(0,Ui.dp(this,8),0,0);root.addView(note);
        AdapterView.OnItemSelectedListener changed=new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){if(loaded)mix();}};mode.setOnItemSelectedListener(changed);size.setOnItemSelectedListener(changed);
        connection=new MediaController.Builder(this,new SessionToken(this,new ComponentName(this,PlaybackService.class))).buildAsync();connection.addListener(()->{try{player=connection.get();play.setEnabled(!queue.isEmpty());}catch(Exception e){status.setText("Volte à biblioteca e tente conectar o tocador novamente.");}},handler::post);
        worker.execute(()->{try{List<MediaItem> found=LibraryStore.scan(this);runOnUiThread(()->{if(isDestroyed())return;library.addAll(found);loaded=true;mix();});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed())status.setText("Permita acesso às músicas na biblioteca e abra o DJ novamente.");});}});
    }
    private void mix(){if(!loaded)return;int request=++generation;if(pending!=null)pending.cancel(true);int selectedMode=mode.getSelectedItemPosition(),selectedSize=size.getSelectedItemPosition();getSharedPreferences("dj",0).edit().putInt("mode",selectedMode).putInt("size",selectedSize).apply();play.setEnabled(false);refresh.setEnabled(false);queue.clear();adapter.notifyDataSetChanged();status.setText("Montando sua seleção…");
        long seed=SystemClock.elapsedRealtimeNanos(),now=System.currentTimeMillis();
        pending=worker.submit(()->{List<DjPlanner.Song> songs=DjSession.describe(this,library);Map<String,MediaItem> items=new HashMap<>();for(MediaItem item:library)items.put(item.mediaId,item);
            List<DjPlanner.Song> chosen=DjPlanner.build(songs,DjPlanner.Mode.values()[selectedMode],SIZES[selectedSize],seed,now);runOnUiThread(()->{if(isDestroyed()||request!=generation)return;details.clear();for(DjPlanner.Song song:chosen){queue.add(DjSession.explain(items.get(song.id),DjPlanner.explain(song,DjPlanner.Mode.values()[selectedMode],now),DjPlanner.Mode.values()[selectedMode]));details.put(song.id,song);}adapter.notifyDataSetChanged();refresh.setEnabled(library.size()>1);play.setEnabled(player!=null&&!queue.isEmpty());if(queue.isEmpty())status.setText(selectedMode==1?"Nenhuma favorita disponível para o DJ. Confira as músicas evitadas no menu.":"Nenhuma música disponível para o DJ. Confira a permissão e as músicas evitadas.");else status.setText(queue.size()+" músicas na seleção • "+library.size()+" arquivos na biblioteca");});});
    }
    private void start(int position){if(player==null||queue.isEmpty())return;player.setShuffleModeEnabled(false);player.setRepeatMode(Player.REPEAT_MODE_OFF);player.setMediaItems(new ArrayList<>(queue),position,0);player.prepare();player.play();startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));finish();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==VoiceSearch.REQUEST){String phrase=VoiceSearch.result(result,data);if(!phrase.isEmpty())new VoiceAssistant().interpret(this,phrase,command->{if(!VoiceControl.execute(this,player,command))VoiceControl.say(this,"Use a busca da biblioteca para encontrar músicas por nome.");});}}
    @Override public void onDestroy(){generation++;worker.shutdownNow();handler.removeCallbacksAndMessages(null);if(connection!=null)MediaController.releaseFuture(connection);super.onDestroy();}
}
